sp_widget.client_script:
api.controller = function($http, spUtil) {
  var c = this;

  c.toggleItem = function(item) {
    item.completed = !item.completed;

    // Recalculate progress
    var completed = c.data.items.filter(function(i) {
      return i.completed;
    }).length;
    c.data.completedCount = completed;
    c.data.progressPercent = Math.round(
      (completed / c.data.totalCount) * 100
    );

    // Send to server script
    spUtil.get('onboarding_progress_tracker', {
      sys_id: item.sys_id,
      completed: item.completed
    });
  };
};

sp_widget.css:
/*
===============================================================================
ONBOARDING PROGRESS TRACKER — SPAR Futuristic edition
Paste into the widget's CSS field
Moves the dark cyan/teal dashboard look to the theme's light glass language:
white cards, red-to-green gradient progress fill, animated checklist states.
===============================================================================
*/

/* Container */
.progress-tracker {
  padding: 24px;
  font-family: 'Inter', 'Segoe UI', sans-serif;
}

/* Header */
.tracker-header {
  margin-bottom: 24px;
}
.tracker-title {
  font-size: 1.5rem;
  font-weight: 800;
  color: #0F172A;
  letter-spacing: -0.02em;
  margin-bottom: 4px;
}
.tracker-subtitle {
  font-size: 0.875rem;
  color: #64748B;
}

/* Progress bar */
.progress-section {
  margin-bottom: 32px;
}
.progress-labels {
  display: flex;
  justify-content: space-between;
  margin-bottom: 8px;
}
.progress-text {
  font-size: 0.875rem;
  font-weight: 700;
  color: #0F172A;
}
.progress-percent {
  font-size: 0.875rem;
  color: #64748B;
}
.progress-bar-container {
  position: relative;
  width: 100%;
  height: 14px;
  background: #F1F5F9;
  border: 1px solid #E2E8F0;
  border-radius: 999px;
  overflow: hidden;
  margin-bottom: 8px;
}
.progress-bar-fill {
  position: relative;
  height: 100%;
  background: linear-gradient(135deg, $brand-primary 0%, $brand-success 100%);
  border-radius: 999px;
  overflow: hidden;
  box-shadow: 0 0 10px rgba(227, 6, 19, 0.35);
  transition: width 0.7s cubic-bezier(0.34, 1.56, 0.64, 1);
}
/* Animated shimmer sweeping across the filled portion */
.progress-bar-fill::after {
  content: "";
  position: absolute;
  inset: 0;
  background: linear-gradient(120deg, rgba(255,255,255,0) 0%, rgba(255,255,255,0.55) 50%, rgba(255,255,255,0) 100%);
  transform: translateX(-100%);
  animation: progressShimmer 2.2s ease-in-out infinite;
}
@keyframes progressShimmer {
  to { transform: translateX(100%); }
}
.progress-percent-label {
  font-size: 0.8rem;
  color: $brand-primary;
  font-weight: 700;
  text-align: right;
}

/* Checklist */
.checklist-container {
  display: flex;
  flex-direction: column;
  gap: 12px;
}

.checklist-item {
  position: relative;
  display: flex;
  align-items: center;
  gap: 16px;
  padding: 16px;
  background: rgba(255, 255, 255, 0.9);
  border: 1px solid #E2E8F0;
  border-radius: 12px;
  overflow: hidden;
  transition: transform 250ms cubic-bezier(0.34, 1.56, 0.64, 1),
              box-shadow 250ms ease,
              border-color 250ms ease;
}
.checklist-item::before {
  content: "";
  position: absolute;
  top: 0;
  left: 0;
  bottom: 0;
  width: 3px;
  background: $brand-primary;
  opacity: 0;
  transition: opacity 250ms ease;
}
.checklist-item:hover {
  transform: translateY(-2px);
  box-shadow: 0 8px 20px -4px rgba(227, 6, 19, 0.14);
  border-color: rgba(227, 6, 19, 0.25);
}
.checklist-item:hover::before {
  opacity: 1;
}

/* Status icon circle — pending vs. complete */
.checklist-icon {
  flex-shrink: 0;
  display: flex;
  align-items: center;
  justify-content: center;
  width: 36px;
  height: 36px;
  border-radius: 50%;
  font-size: 0.9rem;
  transition: background 250ms ease, transform 250ms cubic-bezier(0.34,1.56,0.64,1), box-shadow 250ms ease;
}
.checklist-icon--pending {
  background: #F1F5F9;
  border: 2px solid #CBD5E1;
  color: transparent;
}
.checklist-icon--complete {
  background: linear-gradient(135deg, $brand-success 0%, darken($brand-success, 12%) 100%);
  color: #ffffff;
  box-shadow: 0 0 0 4px rgba(0, 122, 51, 0.15);
  animation: checkPop 400ms cubic-bezier(0.34, 1.56, 0.64, 1);
}
@keyframes checkPop {
  0%   { transform: scale(0.4); opacity: 0; }
  60%  { transform: scale(1.15); opacity: 1; }
  100% { transform: scale(1); }
}

.checklist-text {
  display: flex;
  flex-direction: column;
  gap: 2px;
}
.checklist-item-title {
  font-size: 0.9rem;
  font-weight: 700;
  color: #0F172A;
}
.checklist-item-meta {
  font-size: 0.78rem;
  color: #94A3B8;
}

/* Completed items dim slightly and get a strikethrough-free "done" tint */
.checklist-item--complete {
  background: rgba(0, 122, 51, 0.04);
  border-color: rgba(0, 122, 51, 0.20);
}
.checklist-item--complete .checklist-item-title {
  color: #475569;
}

/* Empty state, in case the checklist has nothing to show yet */
.tracker-empty {
  text-align: center;
  padding: 48px;
  color: #94A3B8;
  font-size: 0.875rem;
}

/* Responsive */
@media (max-width: 768px) {
  .checklist-item {
    padding: 12px;
    gap: 12px;
  }
}

sp_widget.script:
(function() {
    // Handle toggle action from client
    if (input && input.sys_id) {
        var updateGr = new GlideRecord('x_2062828_launch_0_x_onboard_checklist_item');
        if (updateGr.get(input.sys_id)) {
            var isCompleted = input.completed === true || input.completed === 'true';
            updateGr.setValue('u_completed', isCompleted ? '1' : '0');
            updateGr.setValue('state', isCompleted ? '3' : '1');
            updateGr.setWorkflow(false);
            updateGr.update();
            data.updated = true;
        }
        return;
    }

    // Load checklist items
    var items = [];
    var totalCount = 0;
    var completedCount = 0;

    var gr = new GlideRecord('x_2062828_launch_0_x_onboard_checklist_item');
    gr.addQuery('assigned_to', gs.getUserID());
    gr.orderBy('u_order');
    gr.query();

    while (gr.next()) {
        totalCount++;
        var completed = gr.getValue('u_completed') == '1' ||
                       gr.getValue('state') == '3';

        if (completed) completedCount++;

        items.push({
            sys_id: gr.getUniqueValue(),
            short_description: gr.getValue('short_description'),
            category: gr.getValue('u_category') || 'General',
            completed: completed,
            order: gr.getValue('u_order')
        });
    }

    var progressPercent = totalCount > 0 ?
        Math.round((completedCount / totalCount) * 100) : 0;

    data.items = items;
    data.totalCount = totalCount;
    data.completedCount = completedCount;
    data.progressPercent = progressPercent;
})();
